INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(1142880, 'Cyber Dragon Nachster', '电子龙次代', 'サイバー・ドラゴン・ネクステア', 'Effect Monster', 'Machine', 'LIGHT', 1, 200, 200, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「电子龙」使用。 ②：从手卡丢弃1只其他怪兽才能发动。这张卡从手卡特殊召唤。 ③：这张卡召唤·特殊召唤的场合，以攻击力或守备力是2100的自己墓地1只机械族怪兽为对象才能发动。那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是机械族怪兽不能特殊召唤。'),
(58069384, 'Cyber Dragon Nova', '电子龙新星', 'サイバー・ドラゴン・ノヴァ', 'XYZ Monster', 'Machine', 'LIGHT', 5, 2100, 1600, '机械族5星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以自己墓地1只「电子龙」为对象才能发动。那只怪兽特殊召唤。 ②：自己·对方回合1次，从自己的手卡·场上（表侧表示）把1只「电子龙」除外才能发动。这张卡的攻击力直到回合结束时上升2100。 ③：这张卡被对方的效果送去墓地的场合才能发动。从额外卡组把1只机械族融合怪兽特殊召唤。'),
(46724542, 'Cyber Dragon Sieger', '电子龙胜利者', 'サイバー・ドラゴン・ズィーガー', 'Link Monster', 'Machine', 'LIGHT', NULL, 2100, NULL, '包含「电子龙」的机械族怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「电子龙」使用。 ②：这张卡没有攻击宣言的自己·对方的战斗阶段，以自己场上1只攻击力2100以上的机械族怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时上升2100。这个效果的发动后，直到回合结束时这张卡的战斗的双方的战斗伤害变成0。'),
(29975188, 'Cyber Dragon Vier', '电子龙四代', 'サイバー・ドラゴン・フィーア', 'Effect Monster', 'Machine', 'LIGHT', 4, 1100, 1600, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「电子龙」使用。 ②：自己对「电子龙」的召唤·特殊召唤成功的场合才能发动。这张卡从手卡守备表示特殊召唤。 ③：只要这张卡在怪兽区域存在，自己场上的全部「电子龙」的攻击力·守备力上升500。'),
(5373478, 'Cyber Dragon Zwei', '电子龙二代', 'サイバー・ドラゴン・ツヴァイ', 'Effect Monster', 'Machine', 'LIGHT', 4, 1500, 1000, '①：这张卡的卡名只要在墓地存在当作「电子龙」使用。 ②：1回合1次，把手卡1张魔法卡给对方观看才能发动。这张卡的卡名直到结束阶段当作「电子龙」使用。 ③：这张卡向对方怪兽攻击的伤害步骤内，这张卡的攻击力上升300。'),
(28053106, 'Cyber Egg Angel', '电子蛋天使', 'サイバー・エッグ・エンジェル', 'Effect Monster', 'Fairy', 'LIGHT', 2, 200, 300, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合才能发动。从卡组把1张「机械天使」魔法卡或者「祝福的教会-仪式教堂」加入手卡。'),
(33093439, 'Cyber Eltanin', '电子天棓四', 'サイバー・エルタニン', 'Effect Monster', 'Machine', 'LIGHT', 10, -1, -1, '这张卡不能通常召唤。从自己墓地以及自己场上的表侧表示怪兽之中把机械族·光属性怪兽全部除外的场合才能特殊召唤。 ①：这张卡的攻击力·守备力变成因为这张卡特殊召唤而除外的怪兽数量×500。 ②：这张卡特殊召唤成功的场合发动。这张卡以外的场上的表侧表示怪兽全部送去墓地。'),
(60600126, 'Cyber Emergency', '紧急呼救电子', 'エマージェンシー・サイバー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只「电子龙」怪兽或者不能通常召唤的机械族·光属性怪兽加入手卡。 ②：对方让这张卡的发动无效，这张卡被送去墓地的场合，丢弃1张手卡才能发动。这张卡加入手卡。'),
(1546123, 'Cyber End Dragon', '电子终极龙', 'サイバー・エンド・ドラゴン', 'Fusion Monster', 'Machine', 'LIGHT', 10, 4000, 2800, '「电子龙」＋「电子龙」＋「电子龙」 这张卡的融合召唤不用上记的卡不能进行。 ①：这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(38265153, 'Cyber Energy Shock', '电脑能量震击', '電脳エナジーショック', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「人造人-念力震慑者」存在的场合，以场上1张卡为对象才能发动。那张卡破坏。这个效果把场上的陷阱卡破坏的场合，可以再从以下效果选择1个适用。 ●选场上1张表侧表示的卡，那个效果直到回合结束时无效。 ●自己场上的全部「人造人-念力震慑者」的攻击力上升800。'),
(91663373, 'Cyber Esper', '电子超能人', 'サイバー・エスパー', 'Effect Monster', 'Machine', 'FIRE', 4, 1200, 1800, '只要这张卡在自己场上表侧攻击表示存在，可以确认对方抽到的卡。'),
(32768230, 'Cyber Eternal', '永恒电子', 'エターナル・サイバー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只机械族「电子」融合怪兽为对象才能发动。那只怪兽回到额外卡组或无视召唤条件特殊召唤。 ②：自己场上的机械族「电子」融合怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(82315403, 'Cyber Eternity Dragon', '电子永久龙', 'サイバー・エタニティ・ドラゴン', 'Fusion Monster', 'Machine', 'LIGHT', 10, 2800, 4000, '「电子龙」怪兽＋机械族怪兽×2 ①：只要自己墓地有机械族融合怪兽存在，这张卡不会成为对方的效果的对象，不会被对方的效果破坏。 ②：融合召唤的这张卡被对方送去墓地的场合才能发动。从自己的手卡·卡组·墓地选1只「电子龙」特殊召唤。 ③：把墓地的这张卡除外才能发动。这个回合，自己场上的融合怪兽不会成为对方的效果的对象，不会被对方的效果破坏。'),
(30655537, 'Cyber Falcon', '机械猎鹰', 'メカファルコン', 'Normal Monster', 'Machine', 'WIND', 4, 1400, 1200, '装备了喷气式引擎的鹰，能够超音速飞行。'),
(76763417, 'Cyber Gymnast', '电子化体操员', 'サイバー・ジムナティクス', 'Effect Monster', 'Warrior', 'EARTH', 4, 800, 1800, '①：1回合1次，丢弃1张手卡，以对方场上1只表侧攻击表示怪兽为对象才能发动。那只对方的表侧攻击表示怪兽破坏。'),
(80316585, 'Cyber Harpie Lady', '神鹰女郎・电子紧身装束', 'ハーピィ・レディ・SB', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1800, 1300, '这个卡名在规则上当作「鹰身女郎」使用。'),
(34124316, 'Cyber Jar', '电子壶', 'サイバーポッド', 'Flip Effect Monster', 'Rock', 'DARK', 3, 900, 900, '①：这张卡反转的场合发动。场上的怪兽全部破坏。那之后，双方从卡组上面把5张卡翻开，那之中的4星以下而可以特殊召唤的怪兽全部表侧攻击表示或里侧守备表示特殊召唤。剩下的翻开的卡全部加入手卡。'),
(19715246, 'Cyber Jormungardr', '电子世界蛇', 'サイバー・ヨルムンガンド', 'Effect Monster', 'Machine', 'LIGHT', 5, 1000, 2100, '这张卡不能通常召唤，用卡的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：对方场上有怪兽存在的场合才能发动。这张卡从手卡特殊召唤。那之后，从卡组选1只「电子龙」特殊召唤或当作装备魔法卡使用给这张卡装备。这个回合，自己不是机械族怪兽不能特殊召唤。 ②：让自己场上1张「电子龙」回到手卡才能发动。从自己的卡组·墓地把1张「融合」加入手卡。'),
(76986005, 'Cyber Kirin', '电子麒麟', 'サイバー・ジラフ', 'Effect Monster', 'Machine', 'LIGHT', 3, 300, 800, '把这张卡做祭品。直到这个回合的结束阶段，这张卡的控制者受到的因效果造成的伤害变成0。'),
(35050257, 'Cyber Larva', '电子幼虫', 'サイバー・ラーバァ', 'Effect Monster', 'Machine', 'LIGHT', 1, 400, 600, '①：这张卡被选择作为攻击对象的场合发动。这个回合，自己受到的全部战斗伤害变成0。 ②：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只「电子幼体」特殊召唤。'),
(4162088, 'Cyber Laser Dragon', '电子镭射龙', 'サイバー・レーザー・ドラゴン', 'Effect Monster', 'Machine', 'LIGHT', 7, 2400, 1800, '这张卡不能通常召唤。这张卡只能通过「光子发生装置」的效果特殊召唤。可以把持有这张卡攻击力以上的攻击力·守备力的1只怪兽破坏。这个效果1回合只能使用1次。'),
(12670770, 'Cyber Network', '电子网络', 'サイバー・ネットワーク', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动后，第3次的自己准备阶段破坏。 ①：1回合1次，场上有「电子龙」存在的场合才能发动。从卡组把1只机械族·光属性怪兽除外。 ②：这张卡从场上送去墓地的场合发动。除外的自己的机械族·光属性怪兽尽可能特殊召唤，自己场上的魔法·陷阱卡全部破坏。这个效果特殊召唤的怪兽不能把效果发动。这个效果发动的回合，自己不能进行战斗阶段。'),
(64268668, 'Cyber Ogre', '电子食人魔', 'サイバー・オーガ', 'Effect Monster', 'Machine', 'EARTH', 5, 1900, 1200, '把这张卡从手卡丢弃去墓地。自己场上存在的1只「电子食人魔」进行的战斗只有1只无效，并且直到下次战斗结束时攻击力上升2000。这个效果在对方回合也能发动。'),
(37057012, 'Cyber Ogre 2', '电子食人魔2', 'サイバー・オーガ・２', 'Fusion Monster', 'Machine', 'EARTH', 7, 2600, 1900, '「电子食人魔」＋「电子食人魔」 这只怪兽的融合召唤只能用上记的卡进行。这张卡进行攻击时，这张卡的攻击力上升攻击对象怪兽的攻击力一半的数值。'),
(30042158, 'Cyber Ouroboros', '电子衔尾蛇', 'サイバー・ウロボロス', 'Effect Monster', 'Machine', 'DARK', 2, 100, 600, '这张卡从游戏中除外时，可以把手卡1张卡送去墓地，从卡组抽1张卡。'),
(76103404, 'Cyber Petit Angel', '电子小天使', 'サイバー・プチ・エンジェル', 'Effect Monster', 'Fairy', 'LIGHT', 2, 300, 200, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合才能发动。从卡组把1只「电子化天使」怪兽或者1张「机械天使的仪式」加入手卡。'),
(29719112, 'Cyber Pharos', '电子灯塔', 'サイバー・ファロス', 'Effect Monster', 'Machine', 'LIGHT', 1, NULL, 2100, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡可以把自己场上1只机械族怪兽解放从手卡特殊召唤。 ②：1回合1次，自己主要阶段才能发动。从自己的手卡·场上把机械族融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ③：自己的融合怪兽被战斗破坏时，把墓地的这张卡除外才能发动。从卡组把1张「力量结合」加入手卡。'),
(3370104, 'Cyber Phoenix', '电子凤凰', 'サイバー・フェニックス', 'Effect Monster', 'Machine', 'FIRE', 4, 1200, 1600, '①：只要这张卡在怪兽区域攻击表示存在，只以自己场上的机械族怪兽1只为对象的魔法·陷阱卡的效果无效化。 ②：这张卡被战斗破坏送去墓地时才能发动。自己从卡组抽1张。'),
(2158562, 'Cyber Prima', '电子化女主角', 'サイバー・プリマ', 'Effect Monster', 'Warrior', 'LIGHT', 6, 2300, 1600, '①：这张卡上级召唤的场合发动。场上的表侧表示的魔法卡全部破坏。'),
(39978267, 'Cyber Raider', '电子袭击者', 'サイバー・レイダー', 'Effect Monster', 'Machine', 'DARK', 4, 1400, 1000, '这张卡召唤·反转召唤·特殊召唤时，从下列效果中选择1项发动： ●选择场上1张装备在怪兽身上的装备卡并将其破坏。 ●选择场上1张装备在怪兽身上的装备卡并将其装备在这张卡身上。'),
(86686671, 'Cyber Repair Plant', '电子修理工厂', 'サイバー・リペア・プラント', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己墓地有「电子龙」存在的场合，可以从以下效果选择1个发动（这张卡的发动时自己墓地有「电子龙」3只以上存在的场合，可以选择两方）。 ●从卡组把1只机械族·光属性怪兽加入手卡。 ●以自己墓地1只机械族·光属性怪兽为对象才能发动。那只机械族·光属性怪兽回到卡组。'),
(33041277, 'Cyber Revsystem', '电子革新系统', 'サイバー・レヴシステム', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·墓地选1只「电子龙」特殊召唤。这个效果特殊召唤的怪兽不会被效果破坏。'),
(89112729, 'Cyber Saurus', '机械恐龙', 'メカ・ザウルス', 'Fusion Monster', 'Machine', 'EARTH', 5, 1800, 1400, '「炸弹先生」＋「双头恐龙王」'),
(90440725, 'Cyber Shadow Gardna', '电子黑影守卫者', 'サイバー・シャドー・ガードナー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方的主要阶段时才能发动。这张卡发动后变成怪兽卡（机械族·地·4星·攻/守?）在自己的怪兽卡区域特殊召唤。这张卡为攻击对象的对方怪兽的攻击宣言时，这张卡的攻击力·守备力变成和对方攻击怪兽相同数值。这张卡在对方的结束阶段时在魔法与陷阱卡区域盖放。这张卡也当作陷阱卡使用。'),
(32393580, 'Cyber Shark', '电子鲨', 'サイバー・シャーク', 'Effect Monster', 'Fish', 'WATER', 5, 2100, 2000, '自己场上有水属性怪兽表侧表示存在的场合，这张卡可以不用解放作召唤。'),
(63224564, 'Cyber Shield', '电子紧身衣', 'サイバー・ボンテージ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「鹰身女郎」或「鹰身女郎三姐妹」才能装备。 ①：装备怪兽的攻击力上升500。'),
(63261835, 'Cyber Slash Harpie Lady', '神鹰女郎・裂碎爪', 'ハーピィ・レディ・SC', 'Synchro Monster', 'Winged Beast', 'WIND', 8, 2600, 1400, '调整＋调整以外的怪兽1只以上 这张卡同调召唤的场合，可以把自己场上1只「鹰身」怪兽当作调整使用。这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「鹰身女郎」使用。 ②：魔法·陷阱卡的效果发动时，以对方场上1只怪兽或者自己场上1只「鹰身」怪兽为对象才能发动。那只怪兽回到手卡。'),
(44865098, 'Cyber Soldier', '机械士兵', '機械の兵隊', 'Normal Monster', 'Machine', 'DARK', 5, 1500, 1700, '护卫机械王的兵队。圆圆的身体到处转动着进行巡逻。'),
(75559356, 'Cyber Soldier of Darkworld', '魔界的机械兵', '魔界の機械兵', 'Normal Monster', 'Machine', 'DARK', 4, 1400, 1200, '暗之力制造的机器士兵，疯狂的将敌人破坏。'),
(63477921, 'Cyber Summon Blaster', '电子召唤爆破器', 'サイバー・サモン・ブラスター', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡已在魔法与陷阱区域存在的状态，每次机械族怪兽特殊召唤成功发动。给与对方300伤害。'),
(49375719, 'Cyber Tutu', '电子化芭蕾裙', 'サイバー・チュチュ', 'Effect Monster', 'Warrior', 'EARTH', 3, 1000, 800, '①：对方场上的怪兽只有持有比这张卡高的攻击力的怪兽的场合，这张卡可以向对方直接攻击。'),
(42600274, 'Cyber Tutubon', '电子舞裙球球', 'サイバー・チュチュボン', 'Effect Monster', 'Warrior', 'EARTH', 5, 1800, 1600, '①：这张卡可以从自己的手卡·场上把1只战士族或者天使族怪兽解放从手卡特殊召唤。 ②：这张卡为仪式召唤而被解放的场合，以自己墓地1张仪式魔法卡为对象才能发动。那张卡加入手卡。'),
(74157028, 'Cyber Twin Dragon', '电子双头龙', 'サイバー・ツイン・ドラゴン', 'Fusion Monster', 'Machine', 'LIGHT', 8, 2800, 2100, '「电子龙」＋「电子龙」 这张卡的融合召唤不用上记的卡不能进行。 ①：这张卡在同1次的战斗阶段中可以作2次攻击。'),
(3657444, 'Cyber Valley', '电子变形谷', 'サイバー・ヴァリー', 'Effect Monster', 'Machine', 'LIGHT', 1, NULL, NULL, '①：可以从以下效果选择1个发动。 ●这张卡被选择作为攻击对象时，把这张卡除外才能发动。自己从卡组抽1张，那之后战斗阶段结束。 ●以自己场上1只表侧表示怪兽和这张卡为对象才能发动。那只自己的表侧表示怪兽和这张卡除外，那之后自己从卡组抽2张。 ●以自己墓地1张卡为对象才能发动。场上的这张卡和1张手卡除外，那之后作为对象的卡回到卡组最上面。'),
(69015963, 'Cyber-Stein', '魔鬼弗兰肯', 'デビル・フランケン', 'Effect Monster', 'Machine', 'DARK', 2, 700, 500, '①：支付5000基本分才能发动。从额外卡组把1只融合怪兽攻击表示特殊召唤。'),
(48766543, 'Cyber-Tech Alligator', '赛博科技飞龙', 'サイバティック・ワイバーン', 'Normal Monster', 'Machine', 'WIND', 5, 2500, 1600, '机械技术强化的翼龙。被龙打败而濒死之际让饲主给半机械化了。'),
(45078193, 'Cyberdark Cannon', '电子暗黑炮', 'サイバー・ダーク・カノン', 'Effect Monster', 'Dragon', 'DARK', 3, 1600, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。从卡组把1只机械族「电子暗黑」怪兽加入手卡。 ②：有这张卡装备的怪兽进行战斗的伤害计算时才能发动。从卡组把1只怪兽送去墓地。 ③：给怪兽装备的这张卡被送去墓地的场合才能发动。自己从卡组抽1张。'),
(5370235, 'Cyberdark Chimera', '电子暗黑客迈拉', 'サイバー・ダーク・キメラ', 'Effect Monster', 'Machine', 'DARK', 4, 800, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡丢弃1张魔法·陷阱卡才能发动。从卡组把1张「力量结合」加入手卡。这个回合，自己不是龙族·机械族的「电子」怪兽不能作为融合素材，自己把怪兽融合召唤的场合只有1次，也能把自己墓地的怪兽除外作为融合素材。 ②：这张卡被送去墓地的场合才能发动。同名卡不在自己墓地存在的1只「电子暗黑」怪兽从卡组送去墓地。'),
(82562802, 'Cyberdark Claw', '电子暗黑爪', 'サイバー・ダーク・クロー', 'Effect Monster', 'Dragon', 'DARK', 3, 1600, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。从卡组把1张「电子暗黑」魔法·陷阱卡加入手卡。 ②：有这张卡装备的怪兽进行战斗的伤害计算时才能发动。从自己的额外卡组把1只怪兽送去墓地。 ③：给怪兽装备的这张卡被送去墓地的场合，以自己墓地1只「电子暗黑」怪兽为对象才能发动。那只怪兽加入手卡。'),
(40418351, 'Cyberdark Dragon', '铠黑龙－电子暗黑龙', '鎧黒竜－サイバー・ダーク・ドラゴン', 'Fusion Monster', 'Machine', 'DARK', 8, 1000, 1000, '「电子暗黑魔角」＋「电子暗黑刃翼」＋「电子暗黑龙骨」 这张卡不用融合召唤不能特殊召唤。 ①：这张卡特殊召唤成功的场合，以自己墓地1只龙族怪兽为对象发动。那只龙族怪兽当作装备卡使用给这张卡装备。 ②：这张卡的攻击力上升这张卡的效果装备的怪兽的攻击力数值以及自己墓地的怪兽数量×100。 ③：这张卡被战斗破坏的场合，作为代替把装备的那只怪兽破坏。'),
(77625948, 'Cyberdark Edge', '电子暗黑刃', 'サイバー・ダーク・エッジ', 'Effect Monster', 'Machine', 'DARK', 4, 800, 800, '①：这张卡召唤成功的场合，以自己墓地1只3星以下的龙族怪兽为对象发动。那只龙族怪兽当作装备卡使用给这张卡装备。 ②：这张卡的攻击力上升这张卡的效果装备的怪兽的攻击力数值。 ③：这张卡可以直接攻击。那个场合，这张卡的攻击力只在那次伤害计算时变成一半。 ④：这张卡被战斗破坏的场合，作为代替把这张卡的效果装备的怪兽破坏。'),
(37542782, 'Cyberdark End Dragon', '铠皇龙－电子暗黑终极龙', '鎧皇竜－サイバー・ダーク・エンド・ドラゴン', 'Fusion Monster', 'Machine', 'DARK', 12, 5000, 3800, '「铠黑龙-电子暗黑龙」＋「电子终结龙」 这张卡用融合召唤以及以下方法才能特殊召唤。 ●把有「电子终结龙」装备的1只自己的10星以下的「电子暗黑」融合怪兽解放的场合可以从额外卡组特殊召唤。 ①：这张卡不受对方发动的效果影响。 ②：1回合1次，可以发动。选自己·对方的墓地1只怪兽给这张卡装备。 ③：这张卡在同1次的战斗阶段中可以作出最多有这张卡的装备卡数量的攻击。'),
(41230939, 'Cyberdark Horn', '电子暗黑角', 'サイバー・ダーク・ホーン', 'Effect Monster', 'Machine', 'DARK', 4, 800, 800, '①：这张卡召唤成功的场合，以自己墓地1只3星以下的龙族怪兽为对象发动。那只龙族怪兽当作装备卡使用给这张卡装备。 ②：这张卡的攻击力上升这张卡的效果装备的怪兽的攻击力数值。 ③：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ④：这张卡被战斗破坏的场合，作为代替把这张卡的效果装备的怪兽破坏。'),
(80033124, 'Cyberdark Impact!', '电子黑暗冲击！', 'サイバーダーク・インパクト！', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·场上·墓地让「电子暗黑魔角」「电子暗黑刃翼」「电子暗黑龙骨」各1张回到持有者卡组，把1只「铠黑龙-电子暗黑龙」从额外卡组融合召唤。'),
(44352516, 'Cyberdark Inferno', '电子黑暗狱火', 'サイバーダーク・インフェルノ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：有装备卡装备的自己场上的「电子暗黑」效果怪兽不会成为对方的效果的对象，不会被对方的效果破坏。 ②：以自己场上1只「电子暗黑」怪兽为对象才能发动。那只怪兽回到持有者手卡，那之后可以把1只「电子暗黑」怪兽召唤。 ③：场上的这张卡被对方的效果破坏的场合才能发动。从卡组把1张「融合」魔法卡加入手卡。'),
(1157683, 'Cyberdark Invasion', '电子黑暗入侵', 'サイバーダーク・インヴェイジョン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，可以从以下效果选择1个发动。「电子暗黑侵略」的以下效果1回合各能选择1次。 ●以自己场上1只「电子暗黑」效果怪兽为对象才能发动。从自己·对方的墓地选1只龙族·机械族怪兽当作攻击力上升1000的装备卡使用给作为对象的怪兽装备。 ●把给机械族怪兽装备的自己场上1张装备卡送去墓地才能发动。选对方场上1张卡破坏。'),
(3019642, 'Cyberdark Keel', '电子暗黑骨', 'サイバー・ダーク・キール', 'Effect Monster', 'Machine', 'DARK', 4, 800, 800, '①：这张卡召唤成功的场合，以自己墓地1只3星以下的龙族怪兽为对象发动。那只龙族怪兽当作装备卡使用给这张卡装备。 ②：这张卡的攻击力上升这张卡的效果装备的怪兽的攻击力数值。 ③：这张卡战斗破坏对方怪兽的场合发动。给与对方300伤害。 ④：这张卡被战斗破坏的场合，作为代替把这张卡的效果装备的怪兽破坏。'),
(64753988, 'Cyberdark Realm', '电子黑暗世界', 'サイバーダーク・ワールド', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以把同名卡不在自己墓地存在的1只「电子暗黑」怪兽从卡组加入手卡。 ②：自己主要阶段才能发动。进行1只「电子暗黑」怪兽的召唤。 ③：「电子暗黑」怪兽的召唤·特殊召唤成功时发动的自身的效果让自己从自己墓地把怪兽装备的场合，也能作为代替从对方墓地装备。'),
(300302028, 'Cyberdark Style (Skill Card)', NULL, NULL, 'Skill Card', 'Zane Truesdal', NULL, NULL, NULL, NULL, NULL),
(56100345, 'Cyberdark Wurm', '电子暗黑亚龙', 'サイバー・ダーク・ヴルム', 'Effect Monster', 'Machine', 'DARK', 5, 800, 2100, '这个卡名的②的效果在决斗中只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「电子龙」使用。 ②：这张卡在手卡·墓地存在，自己的场上或墓地有这张卡以外的机械族「电子」怪兽存在的场合，从手卡·卡组把1只「电子龙」怪兽送去墓地才能发动。这张卡特殊召唤。那之后，可以从自己墓地把1张「电子」魔法·陷阱卡或「电子科技」魔法·陷阱卡加入手卡。'),
(18967507, 'Cyberdarkness Dragon', '铠狱龙－电子暗黑冥龙', '鎧獄竜－サイバー・ダークネス・ドラゴン', 'Fusion Monster', 'Machine', 'DARK', 10, 2000, 2000, '「电子暗黑」效果怪兽×5 这张卡用融合召唤才能从额外卡组特殊召唤。 ①：这张卡特殊召唤成功的场合才能发动。从自己墓地选1只龙族怪兽或者机械族怪兽当作装备卡使用给这张卡装备。 ②：这张卡的攻击力上升这张卡的效果装备的怪兽的攻击力数值。 ③：对方把魔法·陷阱·怪兽的效果发动时，把自己场上1张装备卡送去墓地才能发动。那个发动无效并破坏。'),
(55704856, 'Cyberload Fusion', '电子负载结合', 'サイバーロード・フュージョン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己场上以及除外的自己怪兽之中让融合怪兽卡决定的融合素材怪兽回到持有者卡组，把以「电子龙」怪兽为融合素材的那1只融合怪兽从额外卡组融合召唤。这个回合，这个效果特殊召唤的怪兽以外的自己怪兽不能攻击。'),
(96428622, 'Cybernetic Cyclopean', '电控独眼巨人', 'サイバネティック・サイクロプス', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1400, 200, '只要自己手卡数目是0张，这张卡的攻击力上升1000。'),
(58199906, 'Cybernetic Fusion Support', '电子融合支援', 'サイバネティック・フュージョン・サポート', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把基本分支付一半才能发动。这个回合，自己把机械族的融合怪兽融合召唤的场合只有1次，可以把那张融合怪兽卡决定的融合素材怪兽从自己的手卡·场上·墓地选出从游戏中除外，用这些作为融合素材。「电子融合支援」在1回合只能发动1张。'),
(92773018, 'Cybernetic Hidden Technology', '人工脑秘密技术', 'サイバネティック・ヒドゥン・テクノロジー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次对方怪兽进行攻击宣言，把自己场上1只「电子龙」或者作为融合素材有「电子龙」记述的融合怪兽送去墓地才能发动。选择那1只攻击怪兽破坏。'),
(63031396, 'Cybernetic Horizon', '人工脑地平线', 'サイバネティック・ホライゾン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「电子暗黑」卡使用。这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是机械族怪兽不能从额外卡组特殊召唤。 ①：从手卡以及卡组各把1只龙族·机械族的「电子」怪兽送去墓地才能发动（相同属性最多1只）。从卡组把1只龙族·机械族的「电子」怪兽加入手卡，从额外卡组把1只机械族「电子」融合怪兽送去墓地。'),
(59023523, 'Cybernetic Magician', '电控魔术师', 'サイバネティック・マジシャン', 'Effect Monster', 'Spellcaster', 'LIGHT', 6, 2400, 1000, '丢弃1张手卡。直到这个回合的结束阶段前，把场上表侧表示存在的1只怪兽的攻击力变为2000。'),
(82428674, 'Cybernetic Overflow', '人工脑溢出', 'サイバネティック・オーバーフロー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·墓地以及自己场上的表侧表示怪兽之中选「电子龙」任意数量除外（相同等级最多1只）。那之后，选除外数量的对方场上的卡破坏。 ②：场上的这张卡被效果破坏的场合才能发动。从卡组把1张「电子」魔法·陷阱卡或者「电子科技」魔法·陷阱卡加入手卡。'),
(18597560, 'Cybernetic Revolution', '人工脑革命', 'サイバネティック・レボリューション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只「电子龙」解放才能发动。以「电子龙」怪兽为融合素材的1只融合怪兽从额外卡组特殊召唤。这个效果特殊召唤的怪兽不能直接攻击，下个回合的结束阶段破坏。'),
(47295267, 'Cybernetic Zone', '电子科技区', 'サイバネティック・ゾーン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只机械族的融合怪兽，直到发动回合的结束阶段时从游戏中除外。从游戏中除外的怪兽回到场上时，那只怪兽的攻击力变成2倍。下次的自己回合的准备阶段时，成为这张卡的对象的1只机械族的融合怪兽破坏。'),
(37007105, 'Cybersal Cyclone', '电子世界旋风', 'サイバーサル・サイクロン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以对方场上1只连接怪兽为对象才能发动。从自己墓地选连接标记数量和那只怪兽相同的1只怪兽除外，作为对象的怪兽破坏。这个效果除外的自己怪兽的原本种族是电子界族的场合，可以再选对方的魔法与陷阱区域1张表侧表示的卡破坏。'),
(89238128, 'Cyberse Accelerator', '电子界加速人', 'サイバース・アクセラレーター', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 2000, NULL, '衍生物以外的怪兽2只以上 这个卡名的效果1回合只能使用1次。 ①：自己·对方的战斗阶段可以以这张卡所连接区1只电子界族怪兽为对象从以下效果选择1个发动。这个效果发动的回合，这张卡不能攻击。 ●那只怪兽的攻击力直到回合结束时上升2000。 ●这个回合，那只怪兽在同1次的战斗阶段中最多2次可以向怪兽攻击。'),
(91269402, 'Cyberse Beacon', '电子界信标', 'サイバース・ビーコン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：战斗或者对方的效果让自己受到伤害的回合才能发动。从卡组把1只4星以下的电子界族怪兽加入手卡。'),
(42717221, 'Cyberse Clock Dragon', '电子界时脉龙', 'サイバース・クロック・ドラゴン', 'Fusion Monster', 'Cyberse', 'DARK', 7, 2500, 2000, '「时钟翼龙」＋连接怪兽1只以上 ①：这张卡的融合召唤成功时才能发动。把那些素材的连接标记合计数量的卡从自己卡组上面送去墓地。直到下个回合的结束时，其他的自己怪兽不能攻击，这张卡的攻击力上升这个效果送去墓地的数量×1000。 ②：只要自己场上有连接怪兽存在，对方不能把自己场上的其他怪兽作为攻击·效果的对象。 ③：融合召唤的这张卡被对方的效果送去墓地的场合才能发动。从卡组把1张魔法卡加入手卡。'),
(14505685, 'Cyberse Converter', '电子界整流员', 'サイバース・コンバーター', 'Effect Monster', 'Cyberse', 'LIGHT', 2, 1000, 1000, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上的怪兽只有电子界族怪兽的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤成功时，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的种族直到回合结束时变成电子界族。'),
(92422871, 'Cyberse Desavewurm', '电子界封存龙', 'サイバース・ディセーブルム', 'Fusion Monster', 'Cyberse', 'DARK', 6, 2300, 1500, '电子界族的仪式·融合·同调·超量·连接怪兽＋电子界族怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把1只电子界族怪兽特殊召唤。那之后，可以把这张卡的等级变成和这个效果特殊召唤的怪兽相同。 ②：自己场上有连接4以上的电子界族怪兽存在，对方把魔法·陷阱卡的效果发动时，把场上·墓地的这张卡除外才能发动。那个发动无效。'),
(60279710, 'Cyberse Enchanter', '电子界魔法师', 'サイバース・エンチャンター', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 2400, NULL, '怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡是已用「电子界男巫」为素材作连接召唤的场合，以对方场上1只怪兽为对象才能发动。那只怪兽的表示形式变更，那个效果直到回合结束时无效化。这个效果在对方回合也能发动。 ②：这张卡被战斗或者对方的效果破坏的场合才能发动。从自己的手卡·卡组·墓地选1只「电子界男巫」特殊召唤。'),
(645087, 'Cyberse Gadget', '电子界小工具', 'サイバース・ガジェット', 'Effect Monster', 'Cyberse', 'LIGHT', 4, 1400, 300, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时，以自己墓地1只2星以下的怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：这张卡从场上送去墓地的场合才能发动。在自己场上把1只「工具衍生物」（电子界族·光·2星·攻/守0）特殊召唤。'),
(25200959, 'Cyberse Integrator', '电子界输送仪', 'サイバース・インテグレーター', 'Synchro Monster', 'Cyberse', 'LIGHT', 3, 1000, 1000, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤成功的场合才能发动。从自己的手卡·墓地选1只电子界族调整守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是电子界族怪兽不能特殊召唤。 ②：同调召唤的这张卡被送去墓地的场合才能发动。自己从卡组抽1张。'),
(24731391, 'Cyberse Magician', '电子界魔术师', 'サイバース・マジシャン', 'Ritual Effect Monster', 'Cyberse', 'DARK', 7, 2500, 2000, '「电脑网仪式」降临。 ①：只要这张卡在怪兽区域存在，自己受到的全部伤害变成一半。 ②：只要自己场上有连接怪兽存在，对方不能选择自己场上的其他怪兽作为攻击对象，也不能作为效果的对象。 ③：只在这张卡和连接怪兽进行战斗的伤害计算时让这张卡的攻击力上升1000。 ④：这张卡被对方的效果破坏的场合才能发动。从卡组把1只电子界族怪兽加入手卡。'),
(63533837, 'Cyberse Quantum Dragon', '电子界量子龙', 'サイバース・クアンタム・ドラゴン', 'Synchro Monster', 'Cyberse', 'DARK', 7, 2500, 2000, '调整＋调整以外的怪兽1只以上 ①：只要自己场上有连接怪兽存在，对方不能选择这张卡以外的自己场上的怪兽作为攻击对象，也不能作为效果的对象。 ②：1回合1次，这张卡和对方怪兽进行战斗的伤害步骤开始时才能发动。那只对方怪兽回到持有者手卡。这个效果发动的场合，这张卡只再1次可以继续攻击。'),
(56337500, 'Cyberse Reminder', '电子界提示者', 'サイバース・リマインダー', 'XYZ Monster', 'Cyberse', 'LIGHT', 3, 1800, 800, '3星怪兽×2 这个卡名的①②的效果1回合各能使用1次，这张卡的效果发动的回合，自己不是电子界族怪兽不能从额外卡组特殊召唤。 ①：把这张卡1个超量素材取除，以自己墓地1张「电脑网」魔法·陷阱卡为对象才能发动。那张卡加入手卡。 ②：超量召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把2只电子界族·4星怪兽效果无效特殊召唤（同名卡最多1张）。'),
(65037172, 'Cyberse Sage', '电子界低调贤者', 'サイバース・セイジ', 'Ritual Effect Monster', 'Cyberse', 'DARK', 1, NULL, NULL, '「电脑网仪式」降临。这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从自己的场上·墓地把融合怪兽卡决定的包含电子界族怪兽的融合素材怪兽除外，把那1只融合怪兽从额外卡组融合召唤。 ②：这张卡作为同调素材送去墓地的场合，以自己墓地1只电子界族怪兽或者1张仪式魔法卡为对象才能发动。那张卡加入手卡。'),
(86784733, 'Cyberse Synchron', '电子界同步士', 'サイバース・シンクロン', 'Tuner Monster', 'Cyberse', 'DARK', 1, 100, 100, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，以自己场上1只4星以下的怪兽为对象才能发动。那只怪兽的等级直到回合结束时上升那个原本等级数值。 ②：额外怪兽区域的自己怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(46104361, 'Cyberse White Hat', '电子界白帽', 'サイバース・ホワイトハット', 'Effect Monster', 'Cyberse', 'LIGHT', 6, 1800, 2400, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有相同种族的怪兽2只以上存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡作为连接素材送去墓地的场合才能发动。对方场上的全部怪兽的攻击力直到回合结束时下降1000。'),
(52698008, 'Cyberse Wicckid', '电子界巫师小子', 'サイバース・ウィキッド', 'Link Monster', 'Cyberse', 'DARK', NULL, 800, NULL, '电子界族怪兽2只 这个卡名的③的效果1回合只能使用1次。 ①：连接召唤的这张卡不会被战斗·效果破坏。 ②：这张卡所连接区的电子界族怪兽不会被效果破坏。 ③：这张卡已在怪兽区域存在的状态，这张卡所连接区有怪兽特殊召唤的场合，从自己墓地把1只电子界族怪兽除外才能发动。从卡组把1只电子界族调整加入手卡。'),
(11674673, 'Cyberse Witch', '电子界女巫', 'サイバース・ウィッチ', 'Link Monster', 'Cyberse', 'DARK', NULL, 800, NULL, '电子界族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡所连接区有怪兽特殊召唤的场合，从自己墓地把1张魔法卡除外才能发动。从卡组把1只电子界族仪式怪兽和1张「电脑网仪式」加入手卡。 ②：这张卡的①的效果发动的回合的自己主要阶段，以自己墓地1只4星以下的电子界族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(36033786, 'Cyberse Wizard', '电子界男巫', 'サイバース・ウィザード', 'Effect Monster', 'Cyberse', 'LIGHT', 4, 1800, 800, '①：1回合1次，以对方场上1只攻击表示怪兽为对象才能发动。那只怪兽变成守备表示。这个效果变成守备表示的回合，自己怪兽只能向作为对象的怪兽攻击，自己的电子界族怪兽向作为对象的守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(51020079, 'Cyborg Doctor', '电子人博士', 'サイボーグドクター', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 1500, 1700, '把自己场上存在的1只调整解放发动。和解放怪兽相同属性·等级的1只怪兽从自己墓地特殊召唤。这个效果1回合只能使用1次。'),
(34614910, 'Cyclamen the Rikka Fairy', '六花精仙客至', '六花精シクラン', 'Effect Monster', 'Plant', 'WATER', 4, 1800, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡·场上的这张卡解放，以自己场上最多2只植物族怪兽为对象才能发动。那些怪兽的等级直到回合结束时下降2星。 ②：这张卡被解放送去墓地的回合的结束阶段才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(32828635, 'Cycle of the World', '世界不灭', 'エンドレス・オブ・ザ・ワールド', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己场上的怪兽解放，从手卡把「破灭之女神 露茵」或「终焉之王 迪米斯」仪式召唤。 ②：让这个回合没有送去墓地的这张卡从墓地回到卡组才能发动。从卡组把1张「世界末日」加入手卡。那之后，可以从自己墓地把1只「破灭之女神 露茵」或「终焉之王 迪米斯」加入手卡。'),
(5494820, 'Cyclon Laser', '气旋镭射枪', 'サイクロンレーザー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '只有「超时空战斗机 V形蛇」可以装备。攻击力上升300点。装备这张卡的怪兽攻击守备表示的怪兽时，若攻击力超过那个守备力，给与对方那个数值的战斗伤害。'),
(22147147, 'Cyclone Blade', '旋风剑', '旋風剣', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「命运英雄」的怪兽才能装备。装备怪兽进行攻击的场合，那个伤害步骤结束时把场上1张魔法或者陷阱卡破坏。'),
(29612557, 'Cyclone Boomerang', '旋风回力镖', 'サイクロン・ブーメラン', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「元素英雄 荒野侠」才能装备。装备怪兽攻击力上升500。装备怪兽被其他卡的效果破坏送去墓地时，场上的魔法·陷阱卡全部破坏。给与对方基本分破坏的魔法·陷阱卡数量×100的伤害。'),
(21036656, 'Cyclos the Circular Sprite', '圆唤妖精 基克罗斯', '円喚妖精キクロス', 'Tuner Monster', 'Plant', 'WIND', 4, 1000, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，丢弃1张手卡才能发动。从卡组把「圆唤妖精 蘑菇圈」以外的1只昆虫族·植物族的调整加入手卡。 ②：这张卡在墓地存在的状态，昆虫族·植物族同调怪兽特殊召唤的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(45945685, 'Cycroid', '单车机人', 'サイクロイド', 'Normal Monster', 'Machine', 'EARTH', 3, 800, 1000, '众多交通工具机人中，和人最亲近而深受喜爱的交通工具机人。还可以装备辅助轮喔！'),
(43839002, 'Cynet Backdoor', '电脑网后门', 'サイバネット・バックドア', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只电子界族怪兽为对象才能发动。那只怪兽除外，把持有比那只怪兽的原本攻击力低的攻击力的1只电子界族怪兽从卡组加入手卡。这个效果除外的怪兽在下次的自己准备阶段回到场上，那个回合可以直接攻击。'),
(4433488, 'Cynet Cascade', '电脑网级联', 'サイバネット・カスケード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己对连接怪兽的连接召唤成功的场合，以那1只作为连接素材的自己墓地的怪兽为对象才能发动。那只怪兽特殊召唤。'),
(82886276, 'Cynet Circuit', '电脑网回路', 'サイバネット・サーキット', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「防火」连接怪兽为对象才能发动。从自己墓地选怪兽任意数量在要和作为对象的怪兽成为连接状态的自己或者对方场上特殊召唤。 ②：自己基本分是2000以下的场合，把墓地的这张卡除外才能发动。从自己墓地选1只「防火」连接怪兽回到额外卡组。那之后，可以把那只怪兽从额外卡组特殊召唤。'),
(60018643, 'Cynet Codec', '电脑网编解码', 'サイバネット・コーデック', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的效果在同一连锁上只能发动1次。 ①：「码语者」怪兽从额外卡组往自己场上特殊召唤的场合，以那之内的1只为对象才能发动。属性和那只怪兽相同的1只电子界族怪兽从卡组加入手卡。这个回合，相同属性的怪兽不能用自己的「电脑网编解码」的效果加入手卡。这个效果的发动后，直到回合结束时自己不是电子界族怪兽不能从额外卡组特殊召唤。'),
(7403341, 'Cynet Conflict', '电脑网冲突', 'サイバネット・コンフリクト', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「码语者」怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并除外。直到下个回合的结束时，对方不能把原本卡名和这个效果除外的卡相同的卡的效果发动。'),
(77449773, 'Cynet Crosswipe', '电脑网交叉清除', 'サイバネット・クロスワイプ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：把自己场上1只电子界族怪兽解放，以场上1张卡为对象才能发动。那张卡破坏。'),
(65801012, 'Cynet Fusion', '电脑网结合', 'サイバネット・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·场上把电子界族融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。额外怪兽区域没有自己怪兽存在的场合，也能把自己墓地的电子界族连接怪兽（最多1只）除外作为融合素材。'),
(57160136, 'Cynet Mining', '电脑网挖矿', 'サイバネット・マイニング', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把1张手卡送去墓地才能发动。从卡组把1只4星以下的电子界族怪兽加入手卡。'),
(34010534, 'Cynet Optimization', '电脑网优选法', 'サイバネット・オプティマイズ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。把1只电子界族怪兽召唤。这个效果的发动后，直到回合结束时自己不是电子界族怪兽不能从额外卡组特殊召唤。 ②：自己的「码语者」怪兽进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。'),
(73558460, 'Cynet Recovery', '电脑网恢复', 'サイバネット・リカバー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上的连接怪兽被战斗或者对方的效果破坏的场合，以连接怪兽以外的自己墓地1只怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(36368606, 'Cynet Refresh', '电脑网刷新', 'サイバネット・リフレッシュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方的电子界族怪兽的攻击宣言时才能发动。双方的主要怪兽区域的怪兽全部破坏。这个回合的结束阶段把这个效果破坏的电子界族连接怪兽尽可能从墓地往持有者场上特殊召唤。 ②：对方怪兽的效果发动时，把墓地的这张卡除外才能发动。自己场上的电子界族连接怪兽直到回合结束时不受自身以外的卡的效果影响。'),
(19943114, 'Cynet Regression', '电脑网回归', 'サイバネット・リグレッション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己对连接怪兽的特殊召唤成功的场合，以场上1张卡为对象才能发动。那张卡破坏。那之后，自己从卡组抽1张。'),
(34767865, 'Cynet Ritual', '电脑网仪式', 'サイバネット・リチューアル', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '电子界族仪式怪兽的降临必需。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只电子界族仪式怪兽仪式召唤。 ②：自己场上没有怪兽存在的场合，从自己墓地把这张卡和1只仪式怪兽除外才能发动。在自己场上把2只「电脑网衍生物」（电子界族·光·4星·攻/守0）特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(57900671, 'Cynet Rollback', '电脑网回滚', 'サイバネット・ロールバック', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以除外的1只自己的电子界族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：自己基本分是2000以下的场合，自己主要阶段把墓地的这张卡除外，以除外的2只自己的电子界族怪兽为对象才能发动。那些怪兽加入手卡。'),
(42461852, 'Cynet Storm', '电脑网风暴', 'サイバネット・ストーム', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的连接状态的怪兽的攻击力·守备力上升500。 ②：只要这张卡在场地区域存在，连接怪兽的连接召唤不会被无效化。 ③：自己受到2000以上的战斗·效果伤害的场合才能发动。只把自己的额外卡组的里侧表示的卡洗切，那张最上面的卡翻开。翻开的卡是电子界族连接怪兽的场合，那只怪兽特殊召唤。不是的场合回到原状。'),
(61583217, 'Cynet Universe', '电脑网宇宙', 'サイバネット・ユニバース', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上的连接怪兽的攻击力上升300。 ②：1回合1次，以自己或者对方的墓地1只怪兽为对象才能发动。那只怪兽回到持有者卡组。 ③：场上的这张卡被效果破坏的场合发动。额外怪兽区域的怪兽全部送去墓地。'),
(43405287, 'D - Chain', 'D-锁链', 'D－チェーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「命运英雄」怪兽为对象才能把这张卡发动。这张卡当作攻击力上升500的装备卡使用给那只自己怪兽装备。 ②：装备怪兽战斗破坏对方怪兽送去墓地的场合发动。给与对方500伤害。'),
(8698851, 'D - Counter', 'D-反击', 'D－カウンター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「命运英雄」的怪兽被选择作为攻击对象时才能发动。攻击怪兽破坏。'),
(6186304, 'D - Force', 'D－力量', 'D－フォース', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，可以从自己的卡组·墓地把1只「命运英雄 血魔-D」加入手卡。 ②：只要自己场上有「命运英雄 血魔-D」存在，以下效果适用。 ●自己在抽卡阶段不能抽卡。 ●对方不能把自己场上的卡作为效果的对象。 ●自己的怪兽区域的「命运英雄 血魔-D」攻击力上升双方墓地的怪兽数量×100，不会被对方的效果破坏，同1次的战斗阶段中可以作2次攻击。'),
(74329404, 'D - Formation', 'D-构成', 'D－フォーメーション', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己场上表侧表示存在的名字带有「命运英雄」的怪兽被破坏，每有1只给这张卡放置1个D指示物。自己的主要阶段时有怪兽的召唤·特殊召唤成功时，可以把D指示物有2个以上放置的这张卡送去墓地，和召唤·特殊召唤的怪兽同名卡最多2张从自己的卡组·墓地加入手卡。'),
(9201964, 'D - Fortune', 'D-幸运', 'D－フォーチュン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方宣言直接攻击时才能发动。把自己墓地存在的1只名字带有「命运英雄」的怪兽从游戏中除外，战斗阶段结束。'),
(62868900, 'D - Shield', 'D-护盾', 'D－シールド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上攻击表示存在的名字带有「命运英雄」的怪兽成为攻击对象时才能发动。这张卡变成装备卡，把成为攻击对象的怪兽变成守备表示并装备这张卡。装备怪兽不会被战斗破坏。'),
(89899996, 'D - Spirit', 'D-精神', 'D－スピリッツ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上没有名字带有「命运英雄」的怪兽存在的场合，可以从手卡特殊召唤1只4星以下的名字带有「命运英雄」的怪兽。'),
(48032131, 'D - Tactics', 'D－战术', 'D－タクティクス', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己·对方的准备阶段才能发动。自己场上的全部「英雄」怪兽的攻击力上升400。 ②：自己场上有8星以上的「命运英雄」怪兽或者「龙骑士 D-终」特殊召唤的场合才能发动。选对方的手卡·场上·墓地1张卡除外。 ③：魔法与陷阱区域的这张卡被效果破坏的场合才能发动。从卡组把1只「命运英雄」怪兽加入手卡。'),
(99075257, 'D - Time', 'D-时间', 'D－タイム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的名字带有「元素英雄」的怪兽从场上离开时才能发动。把和那只怪兽的等级相同的等级以下的1只名字带有「命运英雄」的怪兽从卡组加入手卡。'),
(99357565, 'D Cubed', 'D3', 'D３', 'Effect Monster', 'Machine', 'DARK', 1, NULL, NULL, '「D3」的②③的效果1回合各能使用1次。 ①：这张卡召唤成功的场合发动。这只怪兽在表侧表示存在期间，也当作「命运英雄」怪兽使用。 ②：把最多2张手卡丢弃才能发动。从自己的手卡·卡组·墓地选丢弃数量的「D3」特殊召唤。这个效果的发动后，直到回合结束时自己不是「命运英雄」怪兽不能召唤·特殊召唤。 ③：这张卡被战斗·效果破坏的场合才能发动。从卡组把1只「命运英雄」怪兽送去墓地。'),
(79279397, 'D-Boyz', 'D少年组', 'Dボーイズ', 'Flip Effect Monster', 'Fiend', 'DARK', 1, 100, 1000, '反转：可以从卡组把「D少年组」任意数量表侧攻击表示特殊召唤。那之后，自己受到这个效果特殊召唤的怪兽数量×1000的数值的伤害。'),
(26841274, 'D-Fusion', 'D－结合', 'D－フュージョン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡的效果融合召唤的场合，不是「命运英雄」怪兽不能作为融合素材。 ①：从自己场上把融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。这个效果特殊召唤的怪兽在这个回合不会被战斗·效果破坏。'),
(81057959, 'D. Human', '龙人', 'ドラゴヒューマン', 'Normal Monster', 'Warrior', 'EARTH', 4, 1300, 1100, '挥动用龙牙打造的剑、拥有龙之力量的战士。'),
(2833249, 'D. Tribe', '龙之血族', '竜の血族', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上所有怪兽，直到结束阶段时为止全部变成龙族。'),
(9910360, 'D.3.S. Frog', '三死青蛙', 'ガエル・サンデス', 'Fusion Monster', 'Aqua', 'WATER', 8, 2500, 2000, '「死亡青蛙」＋「死亡青蛙」＋「死亡青蛙」 这只怪兽融合召唤只能使用上述的卡进行。这张卡的攻击力上升自己墓地存在的「黄泉青蛙」的数量×500的数值。'),
(70074904, 'D.D. Assailant', 'D.D.暗杀者', 'D.D.アサイラント', 'Effect Monster', 'Warrior', 'EARTH', 4, 1700, 1600, '①：这张卡被和对方怪兽的战斗破坏的伤害计算后发动。那些进行战斗的各自怪兽除外。'),
(56790702, 'D.D. Assault Carrier', '异次元的强袭舰', '異次元の強襲艦', 'Effect Monster', 'Machine', 'DARK', 8, 2500, 2500, '这个卡名的①的效果1回合只能使用1次。 ①：除外的自己的卡是3张的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡的攻击宣言之际，自己必须从自己墓地把1张卡除外。'),
(60912752, 'D.D. Borderline', '异次元的境界线', '異次元の境界線', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己墓地里没有魔法卡存在的场合，双方玩家都不能进入战斗阶段。'),
(48148828, 'D.D. Crazy Beast', '异次元的狂兽', '異次元の狂獣', 'Effect Monster', 'Beast', 'EARTH', 3, 1400, 1400, '被这张卡战斗破坏的怪兽从游戏中除外。'),
(24508238, 'D.D. Crow', '异次元乌鸦', 'D.D.クロウ', 'Effect Monster', 'Winged Beast', 'DARK', 1, 100, 100, '①：自己·对方回合，把这张卡从手卡丢弃去墓地，以对方墓地1张卡为对象才能发动。那张卡除外。'),
(33423043, 'D.D. Designator', '异次元的指名者', '異次元の指名者', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '宣言1张卡的名称。确认对方手卡，若被宣言的卡在对方手卡中存在，则将其中1张被宣言的卡从游戏中除外；若被宣言的卡未在对方手卡中存在，则自己随机从游戏中除外1张手卡。'),
(44792253, 'D.D. Destroyer', 'D.D.破坏王', 'D.D.デストロイヤー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1000, 1000, '场上存在的这张卡从游戏中除外时，可以选择对方场上表侧表示存在的1张卡破坏。'),
(8628798, 'D.D. Dynamite', 'D.D.炸药', 'D.D.ダイナマイト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '给与对方基本分对方除外的卡数×300的伤害。'),
(80208158, 'D.D. Esper Star Sparrow', '异次元超能人·星斗罗宾', '異次元エスパー・スター・ロビン', 'Effect Monster', 'Warrior', 'LIGHT', 10, 3000, 1500, '只要这张卡在场上表侧表示存在，对方不能把其他的自己怪兽作为卡的效果的对象，也不能作为攻击对象。此外，这张卡在墓地存在的场合，对方怪兽的直接攻击宣言时才能发动。这张卡从墓地表侧守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合从游戏中除外。「异次元超能人·星斗罗宾」在场上只能有1只表侧表示存在。'),
(52702748, 'D.D. Guide', '异次元的案内人', '異次元への案内人', 'Effect Monster', 'Warrior', 'DARK', 4, 1400, 1000, '这张卡召唤成功时，这张卡的控制权转移给对方。每次结束阶段，对方选择这张卡的控制者的墓地里的1张卡从游戏中除外。'),
(15574615, 'D.D. Jet Iron', '异次元喷气机·大铁号', '異次元ジェット・アイアン号', 'Effect Monster', 'Machine', 'LIGHT', 10, 4000, NULL, '这张卡不能通常召唤。从自己的手卡·场上把「异次元超能人·星斗罗宾」「野兽战士 豹人」「凤王兽 铠楼罗」「铁巨人 大铁锤」各1只送去墓地的场合可以特殊召唤。此外，可以把自己场上的这张卡解放，选择自己墓地的「异次元超能人·星斗罗宾」「野兽战士 豹人」「凤王兽 铠楼罗」「铁巨人 大铁锤」各1只特殊召唤。'),
(75991479, 'D.D. Patrol Plane', '异次元的哨戒机', '異次元の哨戒機', 'Effect Monster', 'Machine', 'DARK', 3, 1200, 800, '这个卡名的效果1回合只能使用1次。 ①：这张卡被除外的回合的结束阶段才能发动。选自己的手卡·场上·墓地1张卡除外，这张卡攻击表示特殊召唤。'),
(83626916, 'D.D. Post', '异次元邮筒', '異次元ポスト', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上的怪兽的攻击力上升自己的除外状态的卡种类（怪兽·魔法·陷阱）×300。 ②：1回合1次，自己·对方的主要阶段才能发动。从自己的手卡·墓地把1张卡除外。那之后，可以让自己的除外状态的1张卡回到卡组。 ③：这张卡被除外的场合才能发动。这张卡在自己场上表侧表示放置。'),
(3773196, 'D.D. Scout Plane', '异次元的侦察机', '異次元の偵察機', 'Effect Monster', 'Machine', 'DARK', 2, 800, 1200, '①：这张卡被除外的回合的结束阶段发动。除外的这张卡攻击表示特殊召唤（1回合只有1次）。'),
(89015998, 'D.D. Seeker', '异次元的探求者', '異次元の探求者', 'Effect Monster', 'Psychic', 'DARK', 3, 1500, 800, '这个卡名的效果1回合只能使用1次。 ①：以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽直到下个回合的结束阶段除外。这个效果在对方回合也能发动。'),
(16638212, 'D.D. Sprite', '异次元的精灵', '異次元の精霊', 'Tuner Monster', 'Fairy', 'LIGHT', 1, NULL, 100, '①：这张卡可以把自己场上1只表侧表示怪兽除外，从手卡特殊召唤。 ②：这张卡的①的方法特殊召唤的场合，下次的准备阶段发动。为这张卡特殊召唤而除外的怪兽回到场上。'),
(48092532, 'D.D. Survivor', '异次元的生还者', '異次元の生還者', 'Effect Monster', 'Warrior', 'DARK', 4, 1800, 200, '自己场上表侧表示存在的这张卡从游戏中除外的场合，这张卡在结束阶段时特殊召唤到场上。'),
(51701885, 'D.D. Telepon', '瞬嘭D.D.', 'テレポンD.D.', 'Effect Monster', 'Psychic', 'EARTH', 2, 500, 1800, '自己场上表侧表示存在的这张卡从游戏中除外的场合，可以从自己卡组把1只攻击力1500以下的念动力族怪兽从游戏中除外。下次的自己的准备阶段时，这个效果除外的怪兽特殊召唤。'),
(86498013, 'D.D. Trainer', '异次元驯兽师', '異次元トレーナー', 'Normal Monster', 'Fiend', 'DARK', 1, 100, 2000, '被吸入异次元的可怜小矮人。但是现在为了新的目标而每天都在努力着。'),
(5606466, 'D.D. Trap Hole', '异次元的落穴', '異次元の落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方把1只怪兽守备表示盖放时才能发动。盖放的那1只怪兽和自己场上1只怪兽破坏并从游戏中除外。'),
(95291684, 'D.D. Unicorn Knight', '异次元的独角战士', '異次元の一角戦士', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1800, 900, '这张卡不能通常召唤，把这张卡特殊召唤的回合自己不能通常召唤。这张卡在对方场上有怪兽存在，自己场上有调整表侧表示存在的场合可以特殊召唤。这个方法特殊召唤成功时，可以选择从游戏中除外的1只调整以外的3星以下的自己怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(37043180, 'D.D. Warrior', '异次元的战士', '異次元の戦士', 'Effect Monster', 'Warrior', 'EARTH', 4, 1200, 1000, '①：这张卡和怪兽进行战斗的伤害计算后发动。那些进行战斗的各自怪兽除外。'),
(7572887, 'D.D. Warrior Lady', '异次元的女战士', '異次元の女戦士', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1500, 1600, '①：这张卡和对方怪兽进行战斗的伤害计算后才能发动。那些进行战斗的各自怪兽除外。'),
(76552147, 'D.D.D. - Different Dimension Derby', '异次元赛马', 'D・D・D', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以下其中任意种的怪兽在自己场上表侧表示存在的场合，以场上1张卡为对象才能发动。那张卡除外。 ●使用通常怪兽作仪式召唤的怪兽 ●通常怪兽为素材作融合·同调·超量·连接召唤的怪兽'),
(82112775, 'D.D.M. - Different Dimension Master', '异次元之主', 'D・D・M', 'Effect Monster', 'Spellcaster', 'LIGHT', 5, 1700, 1500, '从手卡丢弃1张魔法卡。特殊召唤1只从游戏中除外的持有者为自己的怪兽。这个效果1回合1次，只能在自己的主要阶段发动。'),
(9622164, 'D.D.R. - Different Dimension Reincarnation', '异次元复活', 'D・D・R', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：丢弃1张手卡，以除外的1只自己怪兽为对象才能把这张卡发动。那只怪兽攻击表示特殊召唤，把这张卡装备。这张卡从场上离开时那只怪兽破坏。'),
(36614113, 'D/D Ark', 'DD 方舟', 'DDアーク', 'Pendulum Effect Monster', 'Fiend', 'DARK', 4, NULL, 2000, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡被效果破坏的场合才能发动。从自己的额外卡组把「DD 方舟」以外的1只表侧表示的「DD」灵摆怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(19808608, 'D/D Berfomet', 'DD 巴风特', 'DDバフォメット', 'Effect Monster', 'Fiend', 'DARK', 4, 1400, 1800, '①：1回合1次，以「DD 巴风特」以外的自己场上1只「DD」怪兽为对象，宣言1～8的任意等级才能发动。那只怪兽直到回合结束时变成宣言的等级。这个效果的发动后，直到回合结束时自己不是「DD」怪兽不能特殊召唤。'),
(39153655, 'D/D Cerberus', 'DD 刻耳柏洛斯', 'DDケルベロス', 'Pendulum Effect Monster', 'Fiend', 'DARK', 4, 1800, 600, '①：这张卡从手卡的灵摆召唤成功时，「DD 刻耳柏洛斯」以外的「DD」怪兽在自己场上存在的场合以自己墓地1张永续魔法卡为对象才能发动。那张卡加入手卡。'),
(5997110, 'D/D Count Surveyor', 'DD 计数测量员', 'DDカウント・サーベイヤー', 'Pendulum Effect Monster', 'Fiend', 'DARK', 8, 2000, 2000, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：从手卡丢弃1只其他的「DD」怪兽才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。把1只攻击力或守备力是0的「DD」怪兽从卡组加入手卡。'),
(93317313, 'D/D Defense Soldier', 'DD 防御士兵', 'DDディフェンス・ソルジャー', 'Effect Monster', 'Fiend', 'DARK', 4, NULL, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：可以从以下效果选择1个发动。 ●以自己的灵摆区域1张「DD」卡为对象才能发动。那张卡特殊召唤。 ●从自己墓地把1只「DD」怪兽除外才能发动。这个回合，自己的「DDD」怪兽攻击的场合，对方直到伤害步骤结束时卡的效果不能发动。 ②：把墓地的这张卡除外才能发动。从自己的额外卡组（表侧）·墓地把1只「DD」灵摆怪兽加入手卡。'),
(32349062, 'D/D Dog', 'DD 猛犬', 'DDドッグ', 'Pendulum Effect Monster', 'Fiend', 'DARK', 6, 2000, 2000, '①：1回合1次，对方对融合·同调·超量怪兽的特殊召唤成功的场合，以那1只怪兽为对象才能发动。这个回合，那只表侧表示怪兽不能攻击，效果无效化。'),
(55415564, 'D/D Evil', 'DD 邪恶', 'DDイービル', 'Pendulum Effect Monster', 'Fiend', 'DARK', 4, 2000, NULL, '这个卡名的②的怪兽效果1回合只能使用1次。 ①：自己场上没有其他的「DD」怪兽存在的场合，这张卡不能攻击。 ②：对方主要阶段，以对方场上1只灵摆召唤的怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。'),
(74387963, 'D/D Extra Surveyor', 'DD 额外测量员', 'DDエクストラ・サーベイヤー', 'Pendulum Effect Monster', 'Fiend', 'DARK', 5, 1000, NULL, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。从自己的额外卡组（表侧）把「DD 额外测量员」以外的1只「DD」灵摆怪兽加入手卡。 ②：这张卡被除外的场合才能发动。把对方的额外卡组的表侧的灵摆怪兽数量的卡从对方卡组上面除外。那之后，可以让自己场上1只「DD」怪兽的攻击力上升这个效果除外的卡数量×200。'),
(33334269, 'D/D Ghost', 'DD 幽灵', 'DDゴースト', 'Tuner Monster', 'Fiend', 'DARK', 2, 600, 300, '①：这张卡被送去墓地的场合，以除「DD 幽灵」外的自己墓地1只「DD」怪兽或1张「契约书」卡为对象才能发动。那1张同名卡从卡组送去墓地。 ②：这张卡被除外的场合，以除「DD 幽灵」外的自己的除外状态的1只「DD」怪兽或1张「契约书」卡为对象才能发动。那张卡回到墓地。'),
(28406301, 'D/D Gryphon', 'DD 狮鹫', 'DDグリフォン', 'Pendulum Effect Monster', 'Fiend', 'DARK', 4, 1200, 1200, '这个卡名的①②③的怪兽效果1回合各能使用1次。 ①：自己场上有「DD」怪兽存在的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：这张卡灵摆召唤的场合，从手卡丢弃1张「DD」卡或「契约书」卡才能发动。自己抽1张。 ③：这张卡从墓地特殊召唤的场合才能发动。从卡组把「DD 狮鹫」以外的1张「DD」卡加入手卡。'),
(19580308, 'D/D Lamia', 'DD 拉弥亚', 'DDラミア', 'Tuner Monster', 'Fiend', 'DARK', 1, 100, 1900, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在的场合，把除「DD 拉弥亚」外的1张「DD」卡或「契约书」卡从自己的手卡·场上（表侧表示）送去墓地才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(67322708, 'D/D Lance Soldier', 'DD 持枪士兵', 'DDランス・ソルジャー', 'Tuner Monster', 'Fiend', 'DARK', 2, 400, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「DD」怪兽为对象才能发动。那只怪兽的等级上升最多有自己的场上·墓地的「契约书」卡数量的数值。 ②：这张卡在墓地存在的场合，以自己场上1张「契约书」卡为对象才能发动。那张卡破坏，这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(12822541, 'D/D Lilith', 'DD 莉莉丝', 'DDリリス', 'Effect Monster', 'Fiend', 'DARK', 4, 100, 2100, '「DD 莉莉丝」的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，可以从以下效果选择1个发动。 ●以自己墓地1只「DD」怪兽为对象才能发动。那只怪兽加入手卡。 ●从自己的额外卡组把1只表侧表示的「DD」灵摆怪兽加入手卡。'),
(72291412, 'D/D Necro Slime', 'DD 死灵史莱姆', 'DDネクロ・スライム', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 300, '这个卡名的效果1回合只能使用1次。 ①：这张卡在墓地存在的场合才能发动。包含这张卡的自己墓地的怪兽作为融合素材除外，把1只「DDD」融合怪兽融合召唤。'),
(48210156, 'D/D Nighthowl', 'DD 暗夜咆哮', 'DDナイト・ハウリング', 'Tuner Monster', 'Fiend', 'DARK', 3, 300, 600, '①：这张卡召唤成功时，以自己墓地1只「DD」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的攻击力·守备力变成0，那只怪兽被破坏的场合自己受到1000伤害。这个效果的发动后，直到回合结束时自己不是恶魔族怪兽不能特殊召唤。'),
(72181263, 'D/D Orthros', 'DD 俄耳托斯', 'DDオルトロス', 'Pendulum Tuner Effect Monster', 'Fiend', 'DARK', 4, 600, 1800, '①：自己因战斗·效果受到伤害时才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤时适用。这个回合，自己不是恶魔族怪兽不能特殊召唤。'),
(32146097, 'D/D Pandora', 'DD 潘朵拉', 'DDパンドラ', 'Effect Monster', 'Fiend', 'DARK', 5, 1700, 2100, '①：这张卡被战斗或者对方的效果破坏送去墓地时，自己场上没有卡存在的场合才能发动。自己从卡组抽2张。'),
(17979378, 'D/D Proud Chevalier', 'DD 高傲骑士', 'DDプラウド・シュバリエ', 'Pendulum Effect Monster', 'Fiend', 'DARK', 5, 2000, 700, '①：这张卡召唤成功时才能发动。从自己的额外卡组把1只表侧表示的暗属性灵摆怪兽加入手卡。'),
(81571633, 'D/D Proud Ogre', 'DD 高傲食人魔', 'DDプラウド・オーガ', 'Pendulum Effect Monster', 'Fiend', 'DARK', 6, 2300, 1500, '①：这张卡召唤成功时才能发动。从自己的额外卡组把1只表侧表示的暗属性灵摆怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，这个效果的发动后，直到回合结束时自己不是「DD」怪兽不能特殊召唤。'),
(8643186, 'D/D Recruits', 'DD 征募', 'DDリクルート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「DD征募」在1回合只能发动1张。 ①：对方场上的怪兽数量比自己场上的怪兽多的场合，以最多有那个相差数量的自己墓地的「DD」怪兽或者「契约书」卡为对象才能发动。那些卡加入手卡。'),
(71069715, 'D/D Reroll', 'DD 重设', 'DDリビルド', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己场上的「契约书」卡不会被对方的效果破坏。 ②：把墓地的这张卡除外，以这张卡以外的除外的最多3张自己的「DD」卡为对象才能发动。那些卡回到卡组。'),
(46796664, 'D/D Savant Copernicus', 'DD 魔导贤者哥白尼', 'DD魔導賢者コペルニクス', 'Pendulum Effect Monster', 'Fiend', 'DARK', 4, NULL, NULL, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。除「DD 魔导贤者 哥白尼」外的1张「DD」卡或「契约书」卡从卡组送去墓地。'),
(74605254, 'D/D Savant Galilei', 'DD 魔导贤者伽利莱', 'DD魔導賢者ガリレイ', 'Pendulum Effect Monster', 'Fiend', 'DARK', 10, NULL, NULL, '「DD 魔导贤者 伽利莱」的怪兽效果1回合只能使用1次。 ①：把这张卡从手卡丢弃，以自己场上1张「DD」卡或者「契约书」卡为对象才能发动。那张卡回到持有者手卡。这个效果在对方回合也能发动。'),
(11609969, 'D/D Savant Kepler', 'DD 魔导贤者开普勒', 'DD魔導賢者ケプラー', 'Pendulum Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合，可以从以下效果选择1个发动。 ●以自己场上1张其他的「DD」卡为对象才能发动。那张卡回到手卡。 ●从卡组把1张「契约书」卡加入手卡。'),
(19302550, 'D/D Savant Newton', 'DD 魔导贤者牛顿', 'DD魔導賢者ニュートン', 'Pendulum Effect Monster', 'Fiend', 'DARK', 7, NULL, NULL, '「DD 魔导贤者 牛顿」的怪兽效果1回合只能使用1次。 ①：把这张卡从手卡丢弃，以「DD 魔导贤者 牛顿」以外的自己墓地1张「DD」卡或者「契约书」卡为对象才能发动。那张卡加入手卡。'),
(46035545, 'D/D Savant Nikola', 'DD 魔导贤者尼古拉', 'DD魔導賢者ニコラ', 'Pendulum Effect Monster', 'Fiend', 'DARK', 6, 2000, 2000, '「DD 魔导贤者 尼古拉」的怪兽效果1回合只能使用1次。 ①：这张卡在灵摆区域被破坏的场合，以自己场上1只「DDD」怪兽为对象才能发动。那只怪兽回到持有者手卡，从自己的额外卡组选最多2只表侧表示的「DD」灵摆怪兽在自己的灵摆区域放置。那些卡的灵摆效果在这个回合不能发动。'),
(41546, 'D/D Savant Thomas', 'DD 魔导贤者托马斯', 'DD魔導賢者トーマス', 'Pendulum Effect Monster', 'Fiend', 'DARK', 8, 1800, 2600, '「DD 魔导贤者 托马斯」的怪兽效果1回合只能使用1次。 ①：以自己的灵摆区域1张「DD」卡为对象才能发动。那张卡破坏，从卡组把1只8星「DDD」怪兽守备表示特殊召唤。这个回合，这个效果特殊召唤的怪兽的效果无效化，对方受到的战斗伤害变成一半。'),
(42382265, 'D/D Scale Surveyor', 'DD 刻度测量员', 'DDスケール・サーベイヤー', 'Pendulum Effect Monster', 'Fiend', 'DARK', 2, NULL, 1000, '这个卡名的①②③的怪兽效果1回合各能使用1次。 ①：自己场上有「DD」灵摆怪兽卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。这张卡的等级变成4星。 ③：这张卡被送去墓地的场合或者表侧加入额外卡组的场合，以自己场上1张「DD」灵摆怪兽卡为对象才能发动。那张卡回到手卡。'),
(45206713, 'D/D Swirl Slime', 'DD 漩涡史莱姆', 'DDスワラル・スライム', 'Effect Monster', 'Fiend', 'DARK', 2, 200, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，自己主要阶段才能发动。包含这张卡的手卡的怪兽作为融合素材，把1只「DDD」融合怪兽融合召唤。 ②：把墓地的这张卡除外才能发动。从手卡把1只「DD」怪兽特殊召唤。'),
(59123937, 'D/D Vice Typhon', 'DD 恶鬼提丰', 'DDヴァイス・テュポーン', 'Effect Monster', 'Fiend', 'DARK', 7, 2300, 2800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功时，把自己场上1只「DD」怪兽解放才能发动。从卡组把1只7星「DDD」怪兽特殊召唤。 ②：这张卡被送去墓地的回合的自己主要阶段才能发动。8星以上的「DDD」融合怪兽卡决定的包含这张卡的融合素材怪兽从自己墓地除外，把那1只融合怪兽从额外卡组融合召唤。'),
(9024198, 'D/D/D Abyss King Gilgamesh', 'DDD 深渊王吉尔伽美什', 'DDD深淵王ビルガメス', 'Link Monster', 'Fiend', 'DARK', NULL, 1800, NULL, '「DD」怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从卡组把2只卡名不同的「DD」灵摆怪兽在自己的灵摆区域放置，自己受到1000伤害。这个效果的发动后，直到回合结束时自己不是「DD」怪兽不能特殊召唤。 ②：连接召唤的这张卡被对方怪兽的攻击或者对方的效果破坏的场合才能发动。从自己的额外卡组·墓地把1只「DD」怪兽守备表示特殊召唤。'),
(11852093, 'D/D/D Alfred the Divine Sage King', 'DDD 圣贤王阿尔弗雷德', 'DDD聖賢王アルフレッド', 'Fusion Monster', 'Fiend', 'DARK', 6, 1500, 2000, '「DD」怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。自己的手卡·场上·除外状态的怪兽作为融合素材回到卡组，把1只「DDD」融合怪兽融合召唤。 ②：这张卡被除外的场合，以最多有自己场上的「DDD」怪兽数量的自己的墓地·除外状态的「契约书」永续魔法·永续陷阱卡为对象才能发动。那些卡在自己场上表侧表示放置。'),
(83303851, 'D/D/D Chaos King Apocalypse', 'DDD 极智王混沌默示录', 'DDD極智王カオス・アポカリプス', 'Pendulum Effect Monster', 'Fiend', 'DARK', 7, 2700, 2000, '「DDD 极智王 混沌默示神」的怪兽效果1回合只能使用1次，对方回合才能发动。 ①：这张卡在手卡·墓地存在的场合，以自己场上2张表侧表示的魔法·陷阱卡为对象才能发动。那些卡破坏，这张卡特殊召唤。这个效果的发动后，直到回合结束时自己不是恶魔族怪兽不能特殊召唤。'),
(811734, 'D/D/D Contract Change', 'DDD的契约变更', 'DDDの契約変更', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时可以从以下效果选择1个发动。 ●选自己墓地1只「DDD」怪兽除外。攻击怪兽的攻击力下降这个效果除外的怪兽的攻击力数值。 ●从卡组把1只4星以下的「DD」灵摆怪兽加入手卡。'),
(44852429, 'D/D/D Cursed King Siegfried', 'DDD 咒血王齐格弗里德', 'DDD呪血王サイフリート', 'Synchro Monster', 'Fiend', 'DARK', 8, 2800, 2200, '调整＋调整以外的「DD」怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：自己·对方回合，以场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张卡的效果直到下次的准备阶段无效。 ②：这张卡被战斗·效果破坏送去墓地的场合发动。自己回复自己场上的「契约书」卡数量×1000基本分。'),
(21686473, 'D/D/D Destiny King Zero Laplace', 'DDD 命运王零拉普拉斯', 'DDD運命王ゼロ・ラプラス', 'Pendulum Effect Monster', 'Fiend', 'DARK', 10, -1, NULL, '①：这张卡可以把自己场上1只「DDD」怪兽解放从手卡特殊召唤。 ②：这张卡和对方怪兽进行战斗的伤害计算前才能发动。这张卡的攻击力直到伤害步骤结束时变成那只对方怪兽的原本攻击力的2倍。 ③：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ④：这张卡1回合只有1次不会被战斗破坏。那个时候，自己受到的战斗伤害变成0。'),
(46593546, 'D/D/D Deviser King Deus Machinex', 'DDD 赦俿王死亡降神', 'DDD赦俿王デス・マキナ', 'XYZ Pendulum Effect Monster', 'Fiend', 'DARK', 10, 3000, 3000, '恶魔族10星怪兽×2 这张卡也能在自己场上的「DDD」怪兽上面重叠来超量召唤。 ①：「DDD 赦俿王 死亡机降神」在自己的怪兽区域只能有1只表侧表示存在。 ②：对方场上的怪兽卡的效果发动时才能发动（同一连锁上最多1次）。这张卡2个超量素材取除或自己场上1张「契约书」卡破坏，那张对方的卡作为这张卡的超量素材。 ③：自己准备阶段才能发动。这张卡在自己的灵摆区域放置。'),
(47198668, 'D/D/D Doom King Armageddon', 'DDD 死伟王地狱末日', 'DDD死偉王ヘル・アーマゲドン', 'Pendulum Effect Monster', 'Fiend', 'DARK', 8, 3000, 1000, '①：1回合1次，自己场上的怪兽被战斗·效果破坏的场合，以那1只怪兽为对象才能发动。这张卡的攻击力直到回合结束时上升作为对象的怪兽的原本攻击力数值。这个效果发动的回合，这张卡不能直接攻击。 ②：这张卡不会被不以这张卡为对象的魔法·陷阱卡的效果破坏。'),
(56619314, 'D/D/D Dragon King Pendragon', 'DDD 霸龙王潘德拉刚', 'DDD覇龍王ペンドラゴン', 'Effect Monster', 'Fiend', 'DARK', 7, 2600, 2400, '①：这张卡在手卡的场合，自己主要阶段从自己的手卡·场上把龙族怪兽和恶魔族怪兽各1只解放才能发动。这张卡从手卡特殊召唤。 ②：1回合1次，自己主要阶段丢弃1张手卡才能发动。这张卡的攻击力直到回合结束时上升500。那之后，可以选场上1张魔法·陷阱卡破坏。'),
(8463720, 'D/D/D Dragonbane King Beowulf', 'DDD 克龙王贝奥武夫', 'DDD剋竜王ベオウルフ', 'Fusion Monster', 'Fiend', 'DARK', 8, 3000, 2500, '「DDD」怪兽＋「DD」怪兽 ①：只要这张卡在怪兽区域存在，自己的「DD」怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ②：自己准备阶段才能发动。双方的魔法与陷阱区域的卡全部破坏。'),
(15939229, 'D/D/D Duo-Dawn King Kali Yuga', 'DDD 双晓王伽梨玉迦', 'DDD双暁王カリ・ユガ', 'XYZ Monster', 'Fiend', 'DARK', 8, 3500, 3000, '8星「DD」怪兽×2 ①：这张卡超量召唤成功的回合，这张卡以外的场上的卡的效果不能发动并无效化。 ②：1回合1次，把这张卡1个超量素材取除才能发动。场上的魔法·陷阱卡全部破坏。这个效果在对方回合也能发动。 ③：把这张卡1个超量素材取除，以自己墓地1张「契约书」魔法·陷阱卡为对象才能发动。那张卡在自己场上盖放。'),
(70576413, 'D/D/D First King Clovis', 'DDD 创始王克洛维斯', 'DDD創始王クロヴィス', 'Synchro Monster', 'Fiend', 'DARK', 6, 2100, 1900, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡同调召唤的场合，以自己的除外状态的1只「DD」怪兽为对象才能发动（场上有「契约书」卡存在的场合，也能作为代替从自己墓地作为对象）。那只怪兽特殊召唤。 ②：这张卡被除外的场合才能发动。这个回合中，自己的「DD」怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(16006416, 'D/D/D Flame High King Genghis', 'DDD 烈火大王执行铁木真', 'DDD烈火大王エグゼクティブ・テムジン', 'Fusion Monster', 'Fiend', 'FIRE', 8, 2800, 2400, '5星以上的「DD」怪兽＋「DD」怪兽 这个卡名的①的效果1回合只能使用1次。 ①：这张卡在怪兽区域存在的状态，自己场上有「DD」怪兽召唤·特殊召唤的场合，以自己墓地1只「DD」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：自己回合1次，魔法·陷阱卡的效果发动时才能发动。那个发动无效。'),
(74583607, 'D/D/D Flame King Genghis', 'DDD 烈火王铁木真', 'DDD烈火王テムジン', 'Fusion Monster', 'Fiend', 'FIRE', 6, 2000, 1500, '「DD」怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：这张卡在怪兽区域存在的状态，自己场上有「DD」怪兽特殊召唤的场合，以自己墓地1只「DD」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡被战斗或者对方的效果破坏的场合，以自己墓地1张「契约书」卡为对象才能发动。那张卡加入手卡。'),
(6766208, 'D/D/D Gust High King Alexander', 'DDD 疾风大王执行亚历山大', 'DDD疾風大王エグゼクティブ・アレクサンダー', 'Synchro Monster', 'Fiend', 'WIND', 10, 3000, 2500, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：场上有「DDD」怪兽3只以上存在的场合，这张卡的攻击力上升3000。 ②：这张卡在怪兽区域存在，自己场上有这张卡以外的「DD」怪兽召唤·特殊召唤的场合，以自己墓地1只「DD」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(987311, 'D/D/D Gust King Alexander', 'DDD 疾风王亚历山大', 'DDD疾風王アレクサンダー', 'Synchro Monster', 'Fiend', 'WIND', 7, 2500, 2000, '「DD」调整＋调整以外的怪兽1只以上 「DDD 疾风王 亚历山大」的效果1回合只能使用1次。 ①：这张卡在怪兽区域存在，自己场上有这张卡以外的「DD」怪兽召唤·特殊召唤的场合，以自己墓地1只4星以下的「DD」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(91781484, 'D/D/D Headhunt', 'DDD猎头', 'DDDヘッドハント', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「DDD」怪兽存在的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的控制权直到下个回合的结束阶段得到。这个效果得到控制权的怪兽的效果无效化，不能攻击宣言。这个效果得到控制权的怪兽是从额外卡组特殊召唤的怪兽的场合，那只怪兽也当作「DDD」怪兽使用。');